function relatedPages(pathname, links=seoRelatedPages[pathname], relativeFeatureLinks=true){
 if(!links?.length)return '';
 return `<nav class="seo-section seo-related" aria-labelledby="seo-related-title"><div class="seo-content"><p class="eyebrow">ПОВ’ЯЗАНІ МАТЕРІАЛИ</p><h2 id="seo-related-title">Що переглянути далі</h2><ul>${links.map(([href,label])=>{const safeHref=relativeFeatureLinks&&/^\/hotel-[a-z0-9-]+$/.test(href)?href.slice(1):href;return `<li><a href="${e(safeHref)}">${e(label)} <span aria-hidden="true">↗</span></a></li>`;}).join('')}</ul></div></nav>`;
}
