function pageContent(config,pathname){
 const primary=config.heroPrimaryHref
  ?`<a class="button" href="${e(config.heroPrimaryHref)}" data-location="seo-page">${e(config.heroCta)} <span aria-hidden="true">↗</span></a>`
  :auditButton(config.heroCta||'Обговорити мій процес',config.heroKind||'audit',config.h1);
 const body=config.sections.map(([eyebrow,title,html])=>section(eyebrow,title,html)).join('');
 const mark = pageMark(pathname);
 const visual = propertyArt(pathname);
 const guide=practicalGuides[pathname];
 const guideHtml=guide?section('ПРАКТИЧНИЙ ЧЕКЛІСТ',guide[0],`<ol>${guide[1].map(item=>`<li>${e(item)}</li>`).join('')}</ol>`):'';
 return `<section class="seo-hero"><div class="seo-wrap seo-hero-grid"><div class="seo-hero-copy"><p class="eyebrow${mark ? ' seo-design-kicker' : ''}">${mark}${e(config.eyebrow||'VDALO / ДЛЯ ГОТЕЛЮ')}</p><h1>${e(config.h1)}</h1><p class="seo-lead">${e(config.lead)}</p>${config.status?`<p class="seo-status-pill"><span>СТАТУС</span>${e(config.status)}</p>`:''}${config.previewNote?`<p class="product-release-preview-note">${e(config.previewNote)}</p>`:''}<div class="seo-hero-actions">${primary}<a class="seo-secondary" href="${e(config.heroSecondaryHref||'/solutions')}">${e(config.heroSecondary||'Переглянути можливості')} <span aria-hidden="true">↗</span></a></div></div>${visual ? `<figure class="seo-hero-visual design-archviz">${visual}</figure>` : `<figure class="seo-hero-visual${config.heroPortrait?' seo-hero-portrait':''}" style="--hero-position:${e(config.heroPosition||'center')}"><img src="/assets/${e(config.heroImage)}" width="${e(config.heroWidth||1536)}" height="${e(config.heroHeight||1024)}" alt="${e(config.heroAlt)}" title="${e(config.heroAlt)}" fetchpriority="high"></figure>`}</div></section>${config.embedded?.()||''}<div class="seo-wrap">${body}${articleBridges[pathname]?articleBridge(pathname):''}${config.extra||''}${guideHtml}${relatedPages(pathname)}</div>`;
}

