function productPageContent(config, pathname) {
 const [parentHref,parentLabel]=config.parent;
 const action=placement=>`<a class="button" href="${e(config.ctaHref||'/contact')}" data-location="product-page" data-cta-placement="${placement}" data-cta-label="${e(config.cta)}">${e(config.cta)} <span aria-hidden="true">↗</span></a>`;
 const icons = productSectionIcons[pathname];
 const sections = config.sections.map(([heading,copy,id], index) => {
  const art = id ? propertyArt('#' + id, true) : '';
  const mark = icons[index] ? `<span class="design-mark" aria-hidden="true">${designIcon(icons[index], {lazy:true})}</span>` : '';
  return `<section class="seo-section${art ? ' product-release-property-detail' : ''}"${id ? ` id="${e(id)}"` : ''}><div class="seo-content">${mark}<h2>${e(heading)}</h2><p>${e(copy)}</p></div>${art}</section>`;
 }).join('');
 const example=config.table
  ? section('',e(config.table.title),`<table class="product-release-table"><thead><tr>${config.table.columns.map(column=>`<th scope="col">${e(column)}</th>`).join('')}</tr></thead><tbody>${config.table.rows.map(([label,...cells])=>`<tr><th scope="row">${e(label)}</th>${cells.map(cell=>`<td>${e(cell)}</td>`).join('')}</tr>`).join('')}</tbody></table>`)
  : section('ПРИКЛАД',e(config.example[0]),`<ol>${config.example[1].map(step=>`<li>${e(step)}</li>`).join('')}</ol>`);
 const faq=section('','Часті запитання',`<div class="product-release-faq">${config.faq.map(([question,answer])=>`<details><summary>${e(question)}</summary><p>${e(answer)}</p></details>`).join('')}</div>`);
 const links=relatedPages(null,config.links,false);
 const previewNote=config.previewNote?`<p class="product-release-preview-note">${e(config.previewNote)}</p>`:'';
 const breadcrumbs=`<nav class="product-release-breadcrumb" aria-label="Навігаційний ланцюжок"><a href="/">Головна</a><span aria-hidden="true">/</span><a href="${e(parentHref)}">${e(parentLabel)}</a><span aria-hidden="true">/</span><span aria-current="page">${e(config.h1)}</span></nav>`;
 const art = propertyArt(pathname);
 const visual = art
  ? `<figure class="product-release-stage product-release-stage-property">${art}</figure>`
  : `<div class="product-release-stage product-release-stage-icon" aria-hidden="true">${pageMark(pathname, '', {hero:true})}</div>`;
 return `<section class="seo-hero product-release-hero"><div class="seo-wrap">${breadcrumbs}<div class="product-release-hero-grid"><div>${previewNote}<h1>${e(config.h1)}</h1><p class="seo-lead">${e(config.lead)}</p><div class="seo-hero-actions">${action('hero')}</div></div>${visual}</div></div></section><div class="seo-wrap product-release-body"><div class="product-release-example">${example}</div><div class="product-release-details">${sections}</div>${faq}<div class="product-release-action">${action('final')}</div>${links}</div>`;
}

